module Rerun

# Raw C bindings (generated by gen/generator.jl from the rerun_c headers).
include(joinpath(@__DIR__, "..", "gen", "LibRerunC.jl"))

# Resolved Arrow datatype model + the generated component/archetype catalog
# (generated by gen/gen_schemas.jl from the vendored Rerun IDL).
include(joinpath(@__DIR__, "arrow_types.jl"))
include(joinpath(@__DIR__, "generated_schemas.jl"))

# Julia-side abstraction layers.
include(joinpath(@__DIR__, "errors.jl"))      # RerunError + checked()
include(joinpath(@__DIR__, "marshal.jl"))     # rr_string / rr_bytes marshalling
include(joinpath(@__DIR__, "cdata.jl"))       # Arrow C Data Interface export
include(joinpath(@__DIR__, "stream.jl"))      # RecordingStream + string-based log
include(joinpath(@__DIR__, "sinks.jl"))       # LogSink sum type + set_sinks
include(joinpath(@__DIR__, "types.jl"))       # Component/Archetype tags + typed log
include(joinpath(@__DIR__, "columns.jl"))     # send_columns (columnar/temporal bulk)
include(joinpath(@__DIR__, "util.jl"))        # entity-path escaping, video timestamps
include(joinpath(@__DIR__, "generated_types.jl"))  # generated component/archetype structs

"""Resolved Arrow datatype for a Rerun component, e.g. `"rerun.components.Position3D"`."""
component_arrow_type(ct::AbstractString) = COMPONENT_TYPES[ct]

"""Field descriptors for a Rerun archetype, e.g. `"rerun.archetypes.Points3D"`."""
archetype_fields(a::AbstractString) = ARCHETYPES[a]

"""Human-readable version string of the linked rerun_c SDK."""
version() = unsafe_string(LibRerunC.rr_version_string())

function __init__()
    _init_callbacks()
    return
end

export RecordingStream, RerunError, LogSink, GrpcSink, FileSink, TimeColumn

end # module Rerun
